fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> bool {
    // We assume arr1.len() == arr2.len() as per the problem statement.
    // For each pair of elements (a, b) at the same index, check that a > b.
    // If all such comparisons hold, return true; otherwise, return false.
    arr1.iter()
        .zip(arr2.iter())
        .all(|(a, b)| a > b)
}

